CREATE TABLE IF NOT EXISTS bill_items(id CHAR(36) PRIMARY KEY,bill_id CHAR(36) NOT NULL,kind VARCHAR(40) NOT NULL,name VARCHAR(120) NOT NULL,amount BIGINT NOT NULL,INDEX idx_bill_item_bill(bill_id));
CREATE TABLE IF NOT EXISTS billing_plans(id CHAR(36) PRIMARY KEY,lease_id CHAR(36) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL,billing_day INT NOT NULL,due_days INT NOT NULL,advance_days INT NOT NULL,next_period_start DATE NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_billing_plan_due(status,next_period_start));
CREATE TABLE IF NOT EXISTS billing_plan_items(id CHAR(36) PRIMARY KEY,plan_id CHAR(36) NOT NULL,kind VARCHAR(40) NOT NULL,name VARCHAR(120) NOT NULL,amount BIGINT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,INDEX idx_billing_plan_item(plan_id,enabled));
CREATE TABLE IF NOT EXISTS billing_runs(id CHAR(36) PRIMARY KEY,trigger_type VARCHAR(30) NOT NULL,period_key VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,actor_id CHAR(36) NULL,total INT NOT NULL DEFAULT 0,succeeded INT NOT NULL DEFAULT 0,failed INT NOT NULL DEFAULT 0,started_at TIMESTAMP NOT NULL,finished_at TIMESTAMP NULL,INDEX idx_billing_run_started(started_at,status));
CREATE TABLE IF NOT EXISTS billing_run_items(id CHAR(36) PRIMARY KEY,run_id CHAR(36) NOT NULL,plan_id CHAR(36) NOT NULL,lease_id CHAR(36) NOT NULL,bill_id CHAR(36) NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,due_date DATE NOT NULL,amount BIGINT NOT NULL,status VARCHAR(30) NOT NULL,error_message VARCHAR(1000) NOT NULL DEFAULT '',attempts INT NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(run_id,plan_id,period_start),INDEX idx_billing_run_item(run_id,status));
